-- =====================================================================
-- CASCO DE VIDRIO — HISTORIAL DE LA HOJA «PARTIR» (29-ene → 8-oct de 2026)
-- ---------------------------------------------------------------------
-- Carga 4174 renglones (fecha · ubicación · SKU · HL) ya sumados: en la
-- hoja había 173 combinaciones repetidas (el mismo día, sitio y SKU en
-- dos renglones) y aquí quedan en uno solo, con los HL sumados.
-- EXPO se une con EXPORTACION: era el mismo cajón escrito de dos formas.
--
-- QUÉ SE GUARDA: PARTIR solo trae el TOTAL (inventario + baja) en HL. Por
-- eso estos renglones quedan con origen = 'importado': el HL es el de la
-- hoja, tal cual, y las estibas = ese HL / HL de una estiba del maestro.
--
-- CORRER DESPUÉS de 2026-10-casco-de-vidrio.sql. SON DOS INSTRUCCIONES
-- INDEPENDIENTES (el editor de Supabase no conserva tablas temporales
-- entre una y otra, así que no se usa ninguna): la carga, y al final la
-- REVISIÓN. Se puede correr dos veces: no duplica ni pisa lo registrado
-- desde la pantalla (solo actualiza renglones importados).
--
-- La REVISIÓN devuelve los materiales cuyo HL de la hoja no da un número
-- entero de estibas con el maestro de hoy. Si sale vacía, el maestro y tu
-- Excel hablan el mismo idioma.
-- =====================================================================

insert into public.casco_registros as r
  (fecha, ubicacion, sku, inventario, hl, hl_estiba, origen, nota)
select p.fecha, p.ubicacion, p.sku,
       case when x.f is not null then round(p.hl / x.f, 2) end,
       p.hl, x.f, 'importado', 'Hoja PARTIR: total inventario + baja, en HL'
