  ) as p(fecha, ubicacion, sku, hl)
  cross join lateral (select public.casco_hl_estiba(p.sku) as f) x
on conflict (fecha, ubicacion, sku) do update set
  inventario = excluded.inventario, hl = excluded.hl, hl_estiba = excluded.hl_estiba,
  actualizado_en = now()
where r.origen = 'importado';

-- REVISIÓN (instrucción aparte): HL importado que no da estibas enteras con
-- el maestro de hoy, o materiales sin factor en el maestro.
select r.sku,
       count(*) as renglones,
       count(*) filter (where r.hl_estiba is null) as sin_factor_en_maestro,
       count(*) filter (where r.hl_estiba is not null
                          and abs(r.hl / r.hl_estiba - round(r.hl / r.hl_estiba)) > 0.02) as no_enteras,
       max(r.hl_estiba) as hl_por_estiba_maestro
  from public.casco_registros r
 where r.origen = 'importado'
 group by r.sku
having count(*) filter (where r.hl_estiba is null) > 0
    or count(*) filter (where r.hl_estiba is not null
                          and abs(r.hl / r.hl_estiba - round(r.hl / r.hl_estiba)) > 0.02) > 0
 order by r.sku;
